<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';tt_require_login();$db=tt_db_open(true);$adsReady=tt_ad_schema_ready($db);$q=trim((string)($_GET['q']??$_POST['q']??''));$selected=trim((string)($_GET['user']??''));$like='%'.$q.'%';if($q!==''){$s=tt_prepare($db,'SELECT `id`,`username`,`aboutcontent`,`tags`,`created_at`,`last_login_at` FROM `accounts` WHERE `username` LIKE ? OR `aboutcontent` LIKE ? OR `tags` LIKE ? ORDER BY `username` LIMIT 100');$s->bind_param('sss',$like,$like,$like);}else{$s=tt_prepare($db,'SELECT `id`,`username`,`aboutcontent`,`tags`,`created_at`,`last_login_at` FROM `accounts` ORDER BY `username` LIMIT 100');}$s->execute();$users=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$posts=[];$ads=[];$selectedOwnerId=0;if($selected!=='' && $adsReady){ $x=tt_prepare($db,'SELECT `id` FROM `accounts` WHERE `username`=? LIMIT 1');$x->bind_param('s',$selected);$x->execute();$x->bind_result($selectedOwnerId);$x->fetch();$x->close(); $x=tt_prepare($db,"SELECT p.`id`,p.`title`,p.`content`,p.`file`,p.`type`,pa.`mime_type` AS attachment_mime,ab.`id` AS boost_id FROM `ad_boosts` ab JOIN `posts` p ON p.`id`=ab.`post_id` LEFT JOIN `post_attachments` pa ON pa.`post_id`=p.`id` WHERE ab.`status`='active' AND ab.`budget_mills`>ab.`spent_mills` AND (ab.`target_username`=? OR ab.`target_username`='') ORDER BY (ab.`target_username`=?) DESC,ab.`budget_mills`-ab.`spent_mills` DESC LIMIT 8");$x->bind_param('ss',$selected,$selected);$x->execute();$ads=$x->get_result()->fetch_all(MYSQLI_ASSOC);$x->close();}if($selected!==''){[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`type`,p.`scope` FROM `posts` p WHERE '.$vis.' AND p.`name`=? ORDER BY p.`dt` DESC LIMIT 50';$params[]=$selected;$types.='s';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$posts=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · People</title></head><body><?php tt_nav('profile.php');?><main class="content"><h2>People</h2><form class="searchbar" method="get"><input name="q" value="<?=tt_h($q)?>" placeholder="Search users, descriptions, tags"><input type="submit" value="Search"></form><section class="grid"><?php foreach($users as $u):?><article class="card"><h3><a href="profile.php?user=<?=urlencode($u['username'])?>"><?=tt_h($u['username'])?></a></h3><p><?=nl2br(tt_h($u['aboutcontent']))?></p><p class="meta"><?=tt_h($u['tags'])?></p><?php if($u['username']!==($_SESSION['name']??'')):?><p><a href="friend.php?user=<?=urlencode($u['username'])?>">Friend controls</a></p><?php endif;?></article><?php endforeach;?></section><?php if($selected!=='' && $ads):?><h2>Sponsored / boosted on <?=tt_h($selected)?>'s page</h2><section class="grid ad-grid"><?php foreach($ads as $a):?><article class="card ad-card" data-boost-id="<?=(int)$a['boost_id']?>" data-page-owner-id="<?=(int)$selectedOwnerId?>"><p class="meta">Sponsored · natural credit exchange enabled</p><h3><a href="post.php#post-<?=(int)$a['id']?>"><?=tt_h($a['title'])?></a></h3><p><?=nl2br(tt_h($a['content']))?></p><?=tt_ad_attachment_html($a)?></article><?php endforeach;?></section><?php endif;?><?php if($selected!==''):?><h2>Posts by <?=tt_h($selected)?></h2><section class="grid"><?php foreach($posts as $p):?><article class="card"><h3><?=tt_h($p['title'])?></h3><p class="meta"><?=tt_h($p['dt'])?> · <?=tt_h($p['type'])?> · <?=tt_h(trim($p['scope']))?></p><p><?=nl2br(tt_h($p['content']))?></p></article><?php endforeach;?><?php if(!$posts):?><article class="card">No visible posts.</article><?php endif;?></section><?php endif;?></main><script>document.querySelectorAll('[data-boost-id]').forEach(el=>{const f=new FormData();f.set('boost_id',el.dataset.boostId);f.set('page_owner_id',el.dataset.pageOwnerId||'0');fetch('ad_impression.php',{method:'POST',body:f,credentials:'same-origin',keepalive:true}).catch(()=>{});});</script></body></html>